// Registers the ONE service worker generated by vite-plugin-pwa.
// Call registerPWA() once from src/main.jsx. Do not add another
// navigator.serviceWorker.register(...) anywhere else in the app.
//
// During `npm run dev` the plugin's devOptions are disabled, so this is a
// harmless no-op. The worker exists only after `npm run build`.
import { registerSW } from 'virtual:pwa-register';
import { markOfflineReady } from './pwaStatus.js';

let registered = false;

export function registerPWA() {
  if (registered || typeof window === 'undefined' || !('serviceWorker' in navigator)) return;
  registered = true;
  registerSW({
    immediate: true,
    onOfflineReady() {
      markOfflineReady();
    },
    onRegisteredSW(_url, registration) {
      // Worker already active from an earlier visit: the app shell is cached.
      if (registration?.active) markOfflineReady();
    },
    onRegisterError(error) {
      console.warn('RuralRise AI: offline support could not be enabled.', error);
    },
  });
}
